SET NAMES utf8mb4;
SET CHARACTER SET utf8mb4;

-- ── สร้างตาราง ──────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS `pipe_repair_docs` (
  `id`          INT           NOT NULL AUTO_INCREMENT,
  `job_id`      VARCHAR(50)   NOT NULL COMMENT 'เลขที่งาน CC-XXXX-NNNNN/FY',
  `job_date`    DATETIME      DEFAULT NULL COMMENT 'วันที่ปิดงาน',
  `contractor`  VARCHAR(120)  NOT NULL DEFAULT '' COMMENT 'ผู้รับจ้าง',
  `note`        VARCHAR(255)  NOT NULL DEFAULT '' COMMENT 'หมายเหตุ',
  `imported_at` DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `source_file` VARCHAR(255)  NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_job_id` (`job_id`),
  KEY `idx_job_date`  (`job_date`),
  KEY `idx_contractor`(`contractor`(40))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='งานซ่อมท่อประปา กปภ.สาขาพิษณุโลก';

-- ── ล้างข้อมูลเดิม ───────────────────────────────────────────────
TRUNCATE TABLE `pipe_repair_docs`;

